import type { IExecuteFunctions, INodeExecutionData } from "n8n-workflow";
import { NodeOperationError } from "n8n-workflow";
import { execa } from "execa";

/**
 * Action runner for 'qsv fmt'
 * Auto-generated by scripts/generate-qsv-nodes.ts
 */
export async function executeFmt(
  this: IExecuteFunctions,
  itemIndex: number,
): Promise<INodeExecutionData[]> {
  const inputPath = this.getNodeParameter("inputPath", itemIndex, "") as string;
  if (!inputPath) {
    throw new NodeOperationError(
      this.getNode(),
      "Input CSV file path is required.",
      { itemIndex },
    );
  }

  const args: string[] = ["fmt"];

  // Collect options and flags
  try {
    const val = this.getNodeParameter("outDelimiter", itemIndex, "") as string;
    if (val !== undefined && val !== "") {
      args.push("--out-delimiter", val);
    }
  } catch {}

  try {
    const val = this.getNodeParameter("crlf", itemIndex, false) as boolean;
    if (val) {
      args.push("--crlf");
    }
  } catch {}

  try {
    const val = this.getNodeParameter("ascii", itemIndex, false) as boolean;
    if (val) {
      args.push("--ascii");
    }
  } catch {}

  try {
    const val = this.getNodeParameter("quote", itemIndex, "") as string;
    if (val !== undefined && val !== "") {
      args.push("--quote", val);
    }
  } catch {}

  try {
    const val = this.getNodeParameter(
      "quoteAlways",
      itemIndex,
      false,
    ) as boolean;
    if (val) {
      args.push("--quote-always");
    }
  } catch {}

  try {
    const val = this.getNodeParameter(
      "quoteNever",
      itemIndex,
      false,
    ) as boolean;
    if (val) {
      args.push("--quote-never");
    }
  } catch {}

  try {
    const val = this.getNodeParameter("escape", itemIndex, "") as string;
    if (val !== undefined && val !== "") {
      args.push("--escape", val);
    }
  } catch {}

  try {
    const val = this.getNodeParameter(
      "noFinalNewline",
      itemIndex,
      false,
    ) as boolean;
    if (val) {
      args.push("--no-final-newline");
    }
  } catch {}

  try {
    const val = this.getNodeParameter("delimiter", itemIndex, "") as string;
    if (val !== undefined && val !== "") {
      args.push("--delimiter", val);
    }
  } catch {}

  try {
    const outputPath = this.getNodeParameter(
      "outputPath",
      itemIndex,
      "",
    ) as string;
    if (outputPath) {
      args.push("--output", outputPath);
    }
  } catch {}

  args.push(inputPath);

  try {
    const { stdout, stderr } = await execa("qsv", args);
    let resultJson: any;

    try {
      resultJson = JSON.parse(stdout);
    } catch {
      resultJson = {
        command: "qsv fmt",
        inputPath,
        rawOutput: stdout,
      };
    }

    return [
      {
        json: {
          success: true,
          command: "fmt",
          inputPath,
          result: resultJson,
        },
      },
    ];
  } catch (error: any) {
    throw new NodeOperationError(
      this.getNode(),
      `Failed executing 'qsv fmt': ${error.stderr || error.message}`,
      { itemIndex },
    );
  }
}
